  var bLong = opt ? parseFloat(opt.getAttribute('data-long')) : 127.0;
  var bLat  = opt ? parseFloat(opt.getAttribute('data-lat'))  : 37.6;
  var bBaseTzOff = opt ? parseFloat(opt.getAttribute('data-base-tz') || opt.getAttribute('data-tz') || '9') : 9;

