  var year=actualDateInfo.y, month=actualDateInfo.m, day=actualDateInfo.d;
  var inputTimeStr = String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0')+':00';

  var bTz = countrySel ? countrySel.value : 'Asia/Seoul';
